index 0000000..94f4868
--- /dev/null
+++ b/app/api/canvas/[id]/chat/messages/route.ts
@@ -0,0 +1,80 @@
+import { NextRequest, NextResponse } from 'next/server';
+import { z } from 'zod';
+
+import { saveMessages } from '@/data/canvas-chat';
+import createLogger from '@/lib/logger';
+import { ERROR_IDS } from '@/constants/errorIds';
+
+const logger = createLogger('api-canvas-chat-messages');
+
+export const runtime = 'nodejs';
+
+const SaveMessagesSchema = z.object({
+  conversationId: z.string().min(1),
+  messages: z.array(
+    z.object({
+      id: z.string().min(1),
+      role: z.enum(['user', 'assistant', 'system']),
+      content: z.string().optional(),
+      parts: z.unknown().optional()
+    })
+  )
+});
+
+/**
+ * POST /api/canvas/[id]/chat/messages
+ * Save messages to a conversation
+ */
+export async function POST(
+  request: NextRequest,
+  { params }: { params: { id: string } }
+) {
+  try {
+    const canvasDraftId = params.id;
+
+    if (!canvasDraftId) {
+      return NextResponse.json(
+        { error: 'Canvas draft ID is required' },
+        { status: 400 }
+      );
+    }
+
+    const body = await request.json();
+    const validated = SaveMessagesSchema.safeParse(body);
+
+    if (!validated.success) {
+      return NextResponse.json(
+        { error: 'Invalid request body', details: validated.error.issues },
+        { status: 400 }
+      );
+    }
+
+    const { conversationId, messages } = validated.data;
+
+    // Convert messages to the expected type (parts as unknown[])
+    const messagesWithTypedParts = messages.map((m) => ({
+      ...m,
+      parts: m.parts as unknown[] | undefined
+    }));
+
+    const result = await saveMessages(
+      conversationId,
+      canvasDraftId,
+      messagesWithTypedParts
+    );
+
+    if (!result.success) {
+      return NextResponse.json({ error: result.error }, { status: 400 });
+    }
+
+    return NextResponse.json({ success: true });
+  } catch (error) {
+    logger.error(ERROR_IDS.CANVAS_CHAT_SAVE_FAILED, {
+      error: error instanceof Error ? error.message : String(error)
+    });
+    return NextResponse.json(
+      { error: ERROR_IDS.CANVAS_CHAT_SAVE_FAILED },
+      { status: 500 }
+    );
+  }
+}
