@@ -0,0 +1,45 @@
+import { NextRequest, NextResponse } from 'next/server';
+
+import { softDeleteConversation } from '@/data/canvas-chat';
+import createLogger from '@/lib/logger';
+import { ERROR_IDS } from '@/constants/errorIds';
+
+const logger = createLogger('api-canvas-chat-reset');
+
+export const runtime = 'nodejs';
+
+/**
+ * POST /api/canvas/[id]/chat/reset
+ * Soft delete the current conversation (reset chat)
+ */
+export async function POST(
+  request: NextRequest,
+  { params }: { params: { id: string } }
+) {
+  try {
+    const canvasDraftId = params.id;
+
+    if (!canvasDraftId) {
+      return NextResponse.json(
+        { error: 'Canvas draft ID is required' },
+        { status: 400 }
+      );
+    }
+
+    const result = await softDeleteConversation(canvasDraftId);
+
+    if (!result.success) {
+      return NextResponse.json({ error: result.error }, { status: 400 });
+    }
+
+    return NextResponse.json({ success: true });
+  } catch (error) {
+    logger.error(ERROR_IDS.CANVAS_CHAT_RESET_FAILED, {
+      error: error instanceof Error ? error.message : String(error)
+    });
+    return NextResponse.json(
+      { error: ERROR_IDS.CANVAS_CHAT_RESET_FAILED },
+      { status: 500 }
+    );
+  }
+}
