@@ -0,0 +1,48 @@
+import { NextRequest, NextResponse } from 'next/server';
+
+import { getOrCreateConversation } from '@/data/canvas-chat';
+import createLogger from '@/lib/logger';
+import { ERROR_IDS } from '@/constants/errorIds';
+
+const logger = createLogger('api-canvas-chat');
+
+export const runtime = 'nodejs';
+
+/**
+ * GET /api/canvas/[id]/chat
+ * Get or create a conversation for a canvas draft
+ */
+export async function GET(
+  request: NextRequest,
+  { params }: { params: { id: string } }
+) {
+  try {
+    const canvasDraftId = params.id;
+
+    if (!canvasDraftId) {
+      return NextResponse.json(
+        { error: 'Canvas draft ID is required' },
+        { status: 400 }
+      );
+    }
+
+    const conversation = await getOrCreateConversation(canvasDraftId);
+
+    if (!conversation) {
+      return NextResponse.json(
+        { error: ERROR_IDS.CANVAS_CHAT_NOT_FOUND },
+        { status: 404 }
+      );
+    }
+
+    return NextResponse.json(conversation);
+  } catch (error) {
+    logger.error(ERROR_IDS.CANVAS_CHAT_FETCH_FAILED, {
+      error: error instanceof Error ? error.message : String(error)
+    });
+    return NextResponse.json(
+      { error: ERROR_IDS.CANVAS_CHAT_FETCH_FAILED },
+      { status: 500 }
+    );
+  }
+}
