diff --git a/data/canvas-chat.ts b/data/canvas-chat.ts
new file mode 100644
index 0000000..dcf9d4f
--- /dev/null
+++ b/data/canvas-chat.ts
@@ -0,0 +1,231 @@
+'use server';
+
+import prisma from '@/lib/prisma';
+import { currentUser } from '@/lib/auth';
+import createLogger from '@/lib/logger';
+import { ERROR_IDS } from '@/constants/errorIds';
+
+const logger = createLogger('data/canvas-chat');
+
+// Type for serialized message matching Vercel AI SDK UIMessage format
+export type ChatMessageData = {
+  id: string;
+  role: 'user' | 'assistant' | 'system';
+  content: string;
+  parts?: unknown[];
+  createdAt: Date;
+};
+
+export type ConversationWithMessages = {
+  id: string;
+  canvasDraftId: string;
+  messages: ChatMessageData[];
+  createdAt: Date;
+  updatedAt: Date;
+};
+
+/**
+ * Get or create an active conversation for a canvas draft
+ * Returns null if user is not authenticated or doesn't own the canvas draft
+ */
+export async function getOrCreateConversation(
+  canvasDraftId: string
+): Promise<ConversationWithMessages | null> {
+  try {
+    const user = await currentUser();
+    if (!user?.id) {
+      logger.warn(ERROR_IDS.LOGIN_REQUIRED, {
+        context: 'getOrCreateConversation'
+      });
+      return null;
+    }
+
+    // Verify user owns this canvas draft
+    const draft = await prisma.canvasDraft.findFirst({
+      where: { id: canvasDraftId, userId: user.id, deletedAt: null }
+    });
+
+    if (!draft) {
+      logger.warn(ERROR_IDS.NO_PERMISSION, {
+        canvasDraftId,
+        userId: user.id
+      });
+      return null;
+    }
+
+    // Find active conversation (not soft-deleted)
+    let conversation = await prisma.canvasChatConversation.findFirst({
+      where: {
+        canvasDraftId,
+        userId: user.id,
+        deletedAt: null
+      },
+      include: {
+        messages: {
+          orderBy: { createdAt: 'asc' }
+        }
+      }
+    });
+
+    // Create new conversation if none exists
+    if (!conversation) {
+      conversation = await prisma.canvasChatConversation.create({
+        data: {
+          canvasDraftId,
+          userId: user.id
+        },
+        include: {
+          messages: true
+        }
+      });
+
+      logger.info('Created new canvas chat conversation', {
+        conversationId: conversation.id,
+        canvasDraftId,
+        userId: user.id
+      });
+    }
+
+    return {
+      id: conversation.id,
+      canvasDraftId: conversation.canvasDraftId,
+      messages: conversation.messages.map((m) => ({
+        id: m.id,
+        role: m.role as 'user' | 'assistant' | 'system',
+        content: m.content || '',
+        parts: m.parts as unknown[] | undefined,
+        createdAt: m.createdAt
+      })),
+      createdAt: conversation.createdAt,
+      updatedAt: conversation.updatedAt
+    };
+  } catch (error) {
+    logger.error(
+      'Error getting or creating conversation',
+      error instanceof Error ? error : { cause: String(error) }
+    );
+    return null;
+  }
+}
+
+/**
+ * Save messages to a conversation (upsert - create if not exists, update if exists)
+ */
+export async function saveMessages(
+  conversationId: string,
+  canvasDraftId: string,
+  messages: Array<{
+    id: string;
+    role: string;
+    content?: string;
+    parts?: unknown[];
+  }>
+): Promise<{ success: boolean; error?: string }> {
+  try {
+    const user = await currentUser();
+    if (!user?.id) {
+      return { success: false, error: ERROR_IDS.LOGIN_REQUIRED };
+    }
+
+    // Verify conversation belongs to user and canvas draft
+    const conversation = await prisma.canvasChatConversation.findFirst({
+      where: {
+        id: conversationId,
+        canvasDraftId,
+        userId: user.id,
+        deletedAt: null
+      }
+    });
+
+    if (!conversation) {
+      return { success: false, error: ERROR_IDS.CANVAS_CHAT_NOT_FOUND };
+    }
+
+    // Upsert messages in a transaction
+    await prisma.$transaction(
+      messages.map((msg) =>
+        prisma.canvasChatMessage.upsert({
+          where: { id: msg.id },
+          update: {
+            content: msg.content || null,
+            parts: msg.parts ? JSON.parse(JSON.stringify(msg.parts)) : null
+          },
+          create: {
+            id: msg.id,
+            conversationId,
+            role: msg.role,
+            content: msg.content || null,
+            parts: msg.parts ? JSON.parse(JSON.stringify(msg.parts)) : null
+          }
+        })
+      )
+    );
+
+    // Update conversation's updatedAt
+    await prisma.canvasChatConversation.update({
+      where: { id: conversationId },
+      data: { updatedAt: new Date() }
+    });
+
+    logger.info('Saved messages to conversation', {
+      conversationId,
+      messageCount: messages.length
+    });
+
+    return { success: true };
+  } catch (error) {
+    logger.error(
+      'Error saving messages',
+      error instanceof Error ? error : { cause: String(error) }
+    );
+    return {
+      success: false,
+      error: error instanceof Error ? error.message : 'Unknown error'
+    };
+  }
+}
+
+/**
+ * Soft delete a conversation (reset chat)
+ * This preserves the conversation history in the database but makes it inaccessible
+ */
+export async function softDeleteConversation(
+  canvasDraftId: string
+): Promise<{ success: boolean; error?: string }> {
+  try {
+    const user = await currentUser();
+    if (!user?.id) {
+      return { success: false, error: ERROR_IDS.LOGIN_REQUIRED };
+    }
+
+    // Soft delete the active conversation
+    const result = await prisma.canvasChatConversation.updateMany({
+      where: {
+        canvasDraftId,
+        userId: user.id,
+        deletedAt: null
+      },
+      data: {
+        deletedAt: new Date(),
+        deletedBy: user.id
+      }
+    });
+
+    logger.info('Soft deleted chat conversation', {
+      canvasDraftId,
+      userId: user.id,
+      conversationsDeleted: result.count
+    });
+
+    return { success: true };
+  } catch (error) {
+    logger.error(
+      'Error soft deleting conversation',
+      error instanceof Error ? error : { cause: String(error) }
+    );
+    return {
+      success: false,
+      error: error instanceof Error ? error.message : 'Unknown error'
+    };
+  }
+}
